export default function activate(api) {
  api.blocks.register({
    id: 'hello-block',
    icon: '✦',
    group: 'advanced',
    label: 'Hello block',
    hint: 'Example slash insert',
    insert: (editor) => {
      editor.chain().focus().insertContent({
        type: 'paragraph',
        content: [{ type: 'text', text: 'Hello from slash-block example' }],
      }).run()
      api.notify.success('Inserted hello block')
    },
  })
}
